SELECT ?z ?label ?t WHERE {
  ?z rdfs:label ?label .
  ?z a ?t .
  FILTER(CONTAINS(?label, "Perimeter_top_ZN_2"))
} LIMIT 50

SELECT ?point ?pclass ?ts ?unit WHERE {
  ?z a brick:HVAC_Zone .
  ?z rdfs:label ?label .
  FILTER(?label IN ("Perimeter_top_ZN_2","DataCenter_bot_ZN_6")) .
  ?z brick:hasPoint ?point .
  ?point a ?pclass .
  OPTIONAL { ?point ref:hasTimeseriesId ?ts }
}

SELECT ?pt ?ptclass ?ts WHERE {
  ?pt a brick:Zone_Air_Temperature_Sensor .
  ?pt brick:isPointOf ?entity .
  ?entity a brick:HVAC_Zone .
